from common import *
import pandas as pd,numpy as np,sqlite3,hashlib
NAMES={'8504':'Transformers, converters and inductors','8507':'Electric accumulators','8541':'Semiconductor devices'}
def decompose(a,b):
 a=a[a.value>0];b=b[b.value>0];m=a.merge(b,on=['hts10','country'],suffixes=('_0','_1'));m=m[m.description_0==m.description_1].copy()
 if m.empty:raise ValueError('No comparable cells')
 w0=m.value_0/m.value_0.sum();w1=m.value_1/m.value_1.sum();r0=m.duty_0/m.value_0;r1=m.duty_1/m.value_1
 within=float((w0*(r1-r0)).sum());mix=float(((w1-w0)*r1).sum());change=float((w1*r1).sum()-(w0*r0).sum());assert abs(within+mix-change)<1e-12
 return dict(full_rate_2025=float(a.duty.sum()/a.value.sum()),full_rate_2026=float(b.duty.sum()/b.value.sum()),balanced_rate_2025=float((w0*r0).sum()),balanced_rate_2026=float((w1*r1).sum()),within_cell_change=within,mix_change=mix,balanced_rate_change=change,coverage_2025=float(m.value_0.sum()/a.value.sum()),coverage_2026=float(m.value_1.sum()/b.value.sum()),balanced_cells=len(m)),m

def sourcing(budget,shift,old,new,premium,fixed):
 if not all(np.isfinite(x) for x in [budget,shift,old,new,premium,fixed]) or budget<0 or not 0<=shift<=1 or min(old,new,fixed)<0 or premium<=-1:raise ValueError('Invalid scenario')
 moved=budget*shift;delta=moved*((1+premium)*(1+new)-(1+old))+(fixed if moved>0 else 0)
 return dict(incremental_budget=delta,shifted_customs_value=moved,maximum_premium_for_breakeven=None if moved==0 else (old-new-fixed/moved)/(1+new))

def main():
 data=pd.concat([pd.read_csv(ROOT/f'data/raw/product-country-{y}.csv',dtype={'hts10':str,'country':str,'hs4':str}) for y in [2025,2026]],ignore_index=True)
 assert (data[['value_aug','duty_aug','value_ytd','duty_ytd']]>=0).all().all();assert not data.duplicated(['year','hts10','country']).any()
 results=[];balances=[];country=[];pairs=[]
 for basis in ['ytd','aug']:
  for hs4 in NAMES:
   sub=data[data.hs4==hs4].rename(columns={f'value_{basis}':'value',f'duty_{basis}':'duty'})
   a=sub[sub.year==2025];b=sub[sub.year==2026];r,m=decompose(a,b);results.append(dict(hs4=hs4,category=NAMES[hs4],basis=basis,whole_category_generalization_gate=r['coverage_2025']>=.8 and r['coverage_2026']>=.8,**r));m['hs4']=hs4;m['basis']=basis;balances.append(m)
   for year,g in sub.groupby('year'):
    c=g.groupby(['country','country_name'],as_index=False)[['value','duty']].sum();c['share']=c.value/c.value.sum();c['historical_duty_ratio']=c.duty/c.value.replace(0,np.nan);c['year']=year;c['hs4']=hs4;c['basis']=basis;country.append(c)
   if basis=='ytd':
    # Selection by import value, before inspection of duty ratios.
    top=b.groupby('country').value.sum().sort_values(ascending=False).head(5).index.tolist()
    for src in top:
     for dst in top:
      if src==dst:continue
      x=b[(b.country==src)&(b.value>0)];z=b[(b.country==dst)&(b.value>0)];q=x.merge(z,on='hts10',suffixes=('_s','_d'));q=q[q.description_s==q.description_d];coverage=q.value_s.sum()/x.value.sum()
      if coverage<.8 or q.empty:continue
      w=q.value_s/q.value_s.sum();rs=float((w*q.duty_s/q.value_s).sum());rd=float((w*q.duty_d/q.value_d).sum());name=x.country_name.iloc[0]+' → '+z.country_name.iloc[0]
      pairs.append(dict(hs4=hs4,source_country=src,alternative_country=dst,label=NAMES[hs4]+': '+name,source_basket_coverage=float(coverage),matched_hts10=len(q),source_fixed_basket_duty_ratio=rs,alternative_fixed_basket_duty_ratio=rd,**sourcing(10000000,.25,rs,rd,.02,50000)))
 result=pd.DataFrame(results);result.to_csv(OUT/'duty_decomposition.csv',index=False,float_format='%.10f');pd.concat(balances).to_csv(OUT/'balanced_cells.csv',index=False,float_format='%.10f');cs=pd.concat(country);cs.to_csv(OUT/'country_exposure.csv',index=False,float_format='%.10f');pair=pd.DataFrame(pairs);assert len(pair)>0,'No pair meets the prespecified 80% source basket threshold';pair.to_csv(OUT/'eligible_sourcing_pairs.csv',index=False,float_format='%.10f')
 # Reconcile aggregate value/duty against separately published commodity totals.
 for year in [2025,2026]:
  totals=json.loads((ROOT/f'data/published-totals-{year}.json').read_text())
  for hs4,v in totals.items():
   g=data[(data.year==year)&(data.hs4==hs4)];assert list(g[['value_aug','duty_aug','value_ytd','duty_ytd']].sum())==v
 con=sqlite3.connect(':memory:');data.to_sql('trade',con,index=False);sql=pd.read_sql_query((ROOT/'reconcile.sql').read_text(),con);sql.to_csv(OUT/'sql_reconciliation.csv',index=False)
 for row in sql.itertuples():
  expected=cs[(cs.year==row.year)&(cs.hs4==row.hs4)&(cs.basis=='ytd')].value.sum();assert row.customs_value==expected
 concentration=[]
 for (year,hs4,basis),g in cs.groupby(['year','hs4','basis']):concentration.append(dict(year=int(year),hs4=hs4,basis=basis,hhi_10000=float(10000*(g.share**2).sum()),largest_origin_share=float(g.share.max())))
 pd.DataFrame(concentration).to_csv(OUT/'concentration.csv',index=False)
 primary=result[result.basis=='ytd'];print(primary.to_string(index=False));print('Eligible pairs:',len(pairs))
 def rates(ax):
  x=np.arange(3);ax.bar(x-.18,primary.full_rate_2025*100,.36,label='Jan-Aug 2025',color=COLORS[0]);ax.bar(x+.18,primary.full_rate_2026*100,.36,label='Jan-Aug 2026',color=COLORS[2]);ax.set_xticks(x);ax.set_xticklabels(['Transformers / converters','Accumulators','Semiconductor devices'],fontsize=9);ax.set_ylabel('Calculated duty / consumption value (%)');ax.legend(frameon=False)
 plot('duty-rates','Historical duty exposure differs across product groups','Observed Census calculated duties and customs values | Matched calendar months, not statutory tariff quotes',rates)
 def bridge(ax):
  x=np.arange(3);within=primary.within_cell_change*100;mix=primary.mix_change*100;ax.bar(x-.2,within,.4,color=COLORS[0],label='Within comparable HTS10/origin cells');ax.bar(x+.2,mix,.4,color=COLORS[1],label='Composition at 2026 cell rates');ax.axhline(0,color='#b2c0d1',lw=.6);ax.set_xticks(x);ax.set_xticklabels(['Transformers / converters\n97% of 2026 value','Accumulators\n47% of 2026 value','Semiconductor devices\n71% of 2026 value'],fontsize=9);ax.set_ylabel('Percentage-point change, balanced panel');ax.legend(frameon=False,fontsize=8)
 plot('duty-decomposition','How much change remains at a fixed starting basket?','Balanced positive-value HTS10/origin cells with identical descriptions | Coverage is reported separately',bridge)
 def cover(ax):
  x=np.arange(3);ax.bar(x-.18,primary.coverage_2025*100,.36,color=COLORS[0],label='2025 value retained');ax.bar(x+.18,primary.coverage_2026*100,.36,color=COLORS[1],label='2026 value retained');ax.set_xticks(x);ax.set_xticklabels(['Transformers / converters','Accumulators','Semiconductor devices'],fontsize=9);ax.set_ylim(0,105);ax.set_ylabel('Share of full customs value (%)');ax.legend(frameon=False)
 plot('comparison-coverage','A comparable panel does not represent all imports','New, exited, zero-value and changed-description cells stay outside the balanced comparison',cover)
 findings='; '.join(f'{r.category}: {100*r.full_rate_2025:.2f}% to {100*r.full_rate_2026:.2f}%' for r in primary.itertuples())+'. These are historical calculated-duty ratios, not legal tariff schedules or causal estimates.'
 limits='Calculated duties are not proof of cash collected, final tariff incidence or supplier cost. HTS10/origin cells can still conceal quality, supplier and timing changes. Identical code descriptions are a conservative comparability screen, not a legal concordance. Balanced-panel results exclude entry/exit and report their coverage. Countries are not suppliers. No quote, product interchangeability, switching feasibility, capacity, delivery time, product-origin eligibility or future tariff rate is established. Retrieved historical files may contain revisions; this is not a point-in-time policy backtest.'
 report='<section class="section"><h2>Question and intended decision</h2><p>Which electrical-equipment categories deserve a sourcing review, and how much of a change in historical duty exposure survives a comparable-product screen? Procurement and finance teams need that distinction before treating a country-level average as a sourcing opportunity.</p><h2>Finding</h2><p>'+findings+'</p>'+figure('duty-rates','Source: Census August bulk files for 2025 and 2026. Primary comparison uses January-August year-to-date imports for consumption; numerator and denominator share the same population.')+table(primary[['category','full_rate_2025','full_rate_2026','balanced_rate_change','within_cell_change','mix_change','coverage_2025','coverage_2026']])+'<h2>Comparable-cell decomposition</h2><p><strong>Coverage gate:</strong> only 46.7% of 2026 accumulator value and 70.5% of semiconductor value enter the strict YTD panel. Their decompositions are diagnostic of those matched cells and must not be generalized to their full categories.</p><p>The starting-basket component holds 2025 customs-value weights fixed and changes cell duty ratios. The composition component then changes weights at 2026 ratios. They sum exactly to the balanced-panel change. This ordered decomposition is descriptive, not a tariff-policy treatment effect.</p>'+figure('duty-decomposition','Changes in percentage points. Rates are duty divided by consumption customs value. Detailed records are aggregated once across districts, subcodes and rate provisions; aggregate world records are not added.')+figure('comparison-coverage','Retained customs-value coverage for each year. Full-population ratios and balanced-panel ratios have different denominators and must not be substituted for each other.')+'<h2>A sourcing scenario with a comparability gate</h2><p>The <a href="workbench.html">interactive sourcing tool</a> uses only origin pairs selected from each category’s five largest 2026 origins by import value before inspecting duty ratios. A pair must share identical-description HTS10 items representing at least 80% of source-origin value. The alternative rate is standardized to the same source basket, not its own country mix.</p><p>A hypothetical annual customs-value budget, reallocation share, supplier-price premium and fixed switching cost turn those historical ratios into an explicit budget illustration. No observed savings or operational recommendation is claimed. Freight and non-duty costs must be supplied separately before operational use.</p><h2>Data audit and reproducibility</h2><p>The raw archive URLs and SHA-256 hashes, selected fixed-width source extracts, source record counts, included code descriptions and exact layout are retained. Both complete detailed archives were scanned. Selected detail totals reconcile exactly to separate published commodity totals for all three groups and both years. SQL independently reconciles aggregated value and duties. August-only sensitivity is also reported, rather than mixing a single month with year-to-date values.</p><h2>Limits</h2><p>'+limits+'</p><h2>Evidence</h2><p><a href="duty_decomposition.csv">Decomposition and coverage</a> · <a href="balanced_cells.csv">Matched cells</a> · <a href="country_exposure.csv">Origin exposure</a> · <a href="eligible_sourcing_pairs.csv">Eligible comparable baskets</a> · <a href="concentration.csv">Country concentration</a> · <a href="sql_reconciliation.csv">SQL reconciliation</a></p><p><a href="https://www.census.gov/foreign-trade/data/dataproducts.html">Official Census bulk files</a> · <a href="https://www.census.gov/foreign-trade/reference/products/layouts/imdb.html">Record layout and units</a>. No API key is required to reproduce from the bulk archives. No bundled Census executables are run.</p></section>'
 page('report.html','Import duties changed. Did the sourcing basket change too?',findings,report)
 tool='<section class="section"><h2>Price a hypothetical sourcing change.</h2><p>Eligible pairs use a common source-weighted product basket with at least 80% source-value coverage. Historical ratios are not current legal tariffs or supplier quotes. All budget, switching and premium inputs below are hypothetical.</p><form id="scenario"><label for="pair">Comparable product and origin pair</label><select id="pair">'+''.join(f'<option value="{i}">'+html.escape(p['label'])+'</option>' for i,p in enumerate(pairs))+'</select><div class="fields"><div><label for="budget">Annual customs-value budget (USD)</label><input id="budget" type="number" min="0" max="1000000000" step="10000" value="10000000" required></div><div><label for="shift">Share shifted (%)</label><input id="shift" type="number" min="0" max="100" step="1" value="25" required></div><div><label for="premium">Replacement supplier-price premium (%)</label><input id="premium" type="number" min="-90" max="100" step="0.1" value="2" required></div><div><label for="fixed">One-off switching cost (USD)</label><input id="fixed" type="number" min="0" max="100000000" step="1000" value="50000" required></div></div><p id="status" role="status" aria-live="polite"></p><div class="metrics"><div class="metric"><b id="cost"></b><span>Illustrative incremental annual budget</span></div><div class="metric"><b id="threshold"></b><span>Break-even supplier-price premium</span></div></div><p id="basket"></p><button id="download" type="button">Download current assumptions and result</button></form><h2>Interpret the calculation</h2><p>Incremental budget = shifted customs value × [(1 + assumed supplier premium) × (1 + alternative historical duty ratio) − (1 + source historical duty ratio)] + one-off switching cost. The fee is charged only if some trade is shifted. A negative result is a conditional budget reduction, not demonstrated savings. Equal freight, quality, delivery and other costs are simplifying assumptions. Country-of-origin rules and future rates must be checked independently before any transaction.</p><p>'+limits+'</p></section>'
 page('workbench.html','What would make a sourcing change worth investigating?','Keep the historical duty evidence separate from the assumptions needed for a business decision.',tool,(OUT/'calculator.js').read_text(),pairs)
 summary=dict(primary_period='January-August 2025 versus January-August 2026',category_results=results,eligible_sourcing_pairs=len(pairs),raw_aggregated_rows=len(data),minimum_pair_coverage=.8)
 dump(OUT/'summary.json',summary);(ROOT/'docs/executive_memo.md').write_text('# Import duty and sourcing tradeoffs\n\n'+findings+'\n\n## Decision use\nPrioritize categories for quote and compliance investigation; do not select a supplier on aggregate historical duty ratios. Separate within-cell rate and composition changes, and inspect excluded value before generalizing.\n\n## Limits\n'+limits+'\n')
if __name__=='__main__':main()
